n = int(input())
for i in range(1, n + 1):
    for j in range(1, i + 1):
        print(j, end=" ")
    print()

def la_nguyen_to(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True


N = int(input())
ds = [x for x in range(2, N + 1) if la_nguyen_to(x)]
if ds:
    print(*ds)
else:
    print("KHONG CO")

a = list(map(int, input().split()))
so_lan_doi = 0
n = len(a)
for i in range(n - 1):
    for j in range(n - 1 - i):
        if a[j] > a[j + 1]:
            a[j], a[j + 1] = a[j + 1], a[j]
            so_lan_doi += 1
print(*a)
print(so_lan_doi)
